"""unbound_flush.py: clear Unbound failures for App Router's forward zones after Apply."""
import subprocess
import types

import pytest

from conftest import load_script

CONF = """\
# Generated by App Router (rules with "Resolve DNS via gateway"). Do not edit.
server:
    local-data: "_approuter-check.71.am. 60 IN TXT approuter"
forward-zone:
    name: "71.am."
    forward-addr: 223.6.6.6
    forward-tcp-upstream: yes
forward-zone:
    name: "iqiyi.com."
    forward-addr: 223.6.6.6
    forward-tcp-upstream: yes
forward-zone:
    name: "bilibili.com."
    forward-addr: 119.29.29.29
    forward-tcp-upstream: yes
"""
ZONES = {"71.am": "223.6.6.6", "iqiyi.com": "223.6.6.6", "bilibili.com": "119.29.29.29"}
DESIRED = [{"dns": "223.6.6.6", "interface": "pgw_China", "gateway": "172.31.175.170"},
           {"dns": "119.29.29.29", "interface": "igc3", "gateway": "10.0.0.1"},
           {"dns": "8.8.8.8", "interface": "igc9", "gateway": "10.9.9.9"}]   # not a forward server: ignored


class FakeRunner:
    """Mocks route(8), unbound-control and drill."""

    def __init__(self, uf, routes=None, rcodes=("NOERROR",), control_rc=0, route_ready_after=0):
        self.uf = uf
        self.routes = routes or {"223.6.6.6": "pgw_China", "119.29.29.29": "igc3"}
        self.rcodes = list(rcodes)
        self.control_rc = control_rc
        self.route_ready_after = route_ready_after
        self.route_calls = 0
        self.calls = []

    def __call__(self, argv, **kw):
        self.calls.append(list(argv))
        if argv[0] == "/sbin/route":
            self.route_calls += 1
            iface = self.routes.get(argv[-1], "igc0")
            if self.route_calls <= self.route_ready_after:
                iface = "igc0"          # still via WAN while the filter settles
            return types.SimpleNamespace(returncode=0, stdout=f"   gateway: x\n interface: {iface}\n", stderr="")
        if argv[0] == self.uf.UNBOUND_CONTROL:
            assert argv[1:3] == ["-c", "/var/unbound/unbound.conf"]
            return types.SimpleNamespace(returncode=self.control_rc, stdout="ok\n" if not self.control_rc else "",
                                         stderr="" if not self.control_rc else "error: connect failed")
        if argv[0] == self.uf.DRILL:
            rcode = self.rcodes.pop(0) if len(self.rcodes) > 1 else self.rcodes[0]
            return types.SimpleNamespace(returncode=0, stdout=f";; ->>HEADER<<- opcode: QUERY, rcode: {rcode}, id: 1\n",
                                         stderr="")
        raise AssertionError(f"unexpected command {argv}")

    def control(self):
        return [c[3:] for c in self.calls if c[0] == self.uf.UNBOUND_CONTROL]


@pytest.fixture
def uf(monkeypatch, tmp_path):
    mod = load_script("unbound_flush")
    monkeypatch.setattr(mod, "log", lambda *a, **k: mod.logged.append(a[0]))
    mod.logged = []
    ctl = tmp_path / "unbound-control"
    ctl.write_text("")
    mod.UNBOUND_CONTROL = str(ctl)
    return mod


def flow(uf, run, **kw):
    sleeps = []
    kw.setdefault("zones", ZONES)
    kw.setdefault("desired", DESIRED)
    kw.setdefault("running", True)
    kw.setdefault("port", 53530)
    kw.setdefault("control", uf.UNBOUND_CONTROL)
    return uf.run_flush(run=run, sleep=sleeps.append, **kw), sleeps


def test_parse_zones():
    uf = load_script("unbound_flush")
    assert uf.parse_zones(CONF) == ZONES
    assert uf.parse_zones("") == {}


def test_flush_commands_only_app_router_zones(uf):
    assert uf.flush_commands(ZONES) == [
        ["flush_infra", "119.29.29.29"], ["flush_infra", "223.6.6.6"],
        ["flush_zone", "71.am"], ["flush_zone", "bilibili.com"], ["flush_zone", "iqiyi.com"],
    ]
    # never the global flushes
    flat = {c[0] for c in uf.flush_commands(ZONES)}
    assert flat == {"flush_infra", "flush_zone"}


def test_happy_path(uf):
    run = FakeRunner(uf)
    result, sleeps = flow(uf, run)
    assert result["status"] == "ok" and result["passes"] == 1
    assert result["check"] == {"71.am": "NOERROR"}
    assert run.control() == uf.flush_commands(ZONES)
    assert sleeps == []
    drill = [c for c in run.calls if c[0] == uf.DRILL]
    assert drill == [[uf.DRILL, "-p", "53530", "71.am", "@127.0.0.1", "A"]]
    assert "flushed Unbound infra cache for 119.29.29.29, 223.6.6.6 and 3 forward zones" in uf.logged[-1]


def test_waits_for_route_before_flushing(uf):
    run = FakeRunner(uf, route_ready_after=3)
    result, sleeps = flow(uf, run)
    assert result["routed"] is True
    assert sleeps == [1, 1, 1]
    first_control = next(i for i, c in enumerate(run.calls) if c[0] == uf.UNBOUND_CONTROL)
    last_route = max(i for i, c in enumerate(run.calls) if c[0] == "/sbin/route")
    assert last_route < first_control


def test_route_never_ready_flushes_anyway(uf):
    run = FakeRunner(uf, routes={"223.6.6.6": "igc0", "119.29.29.29": "igc3"})
    result, sleeps = flow(uf, run)
    assert result["routed"] is False and result["status"] == "ok"
    assert len(sleeps) == uf.ROUTE_WAIT
    assert any("flushing anyway" in m for m in uf.logged)


def test_retries_while_servfail(uf):
    run = FakeRunner(uf, rcodes=["SERVFAIL", "SERVFAIL", "NOERROR"])
    result, sleeps = flow(uf, run)
    assert result["passes"] == 3 and result["check"] == {"71.am": "NOERROR"}
    assert len(run.control()) == 3 * len(uf.flush_commands(ZONES))
    assert sleeps == [uf.VERIFY_DELAY, uf.VERIFY_DELAY]


def test_gives_up_after_max_tries(uf):
    run = FakeRunner(uf, rcodes=["SERVFAIL"])
    result, _ = flow(uf, run)
    assert result["passes"] == uf.VERIFY_TRIES and result["check"] == {"71.am": "SERVFAIL"}


def test_no_zones_does_nothing(uf):
    run = FakeRunner(uf)
    result, _ = flow(uf, run, zones={})
    assert result == {"status": "skipped", "reason": "no forward zones"}
    assert run.calls == [] and uf.logged == []


def test_unbound_control_missing(uf, tmp_path):
    run = FakeRunner(uf)
    result, _ = flow(uf, run, control=str(tmp_path / "nope"))
    assert result["status"] == "skipped" and run.calls == []


def test_unbound_not_running(uf):
    run = FakeRunner(uf)
    result, _ = flow(uf, run, running=False)
    assert result["status"] == "skipped" and run.calls == []


def test_control_errors_are_logged_not_raised(uf):
    run = FakeRunner(uf, control_rc=1)
    result, _ = flow(uf, run)
    assert result["status"] == "failed" and result["passes"] == 1   # no retry when control is broken
    assert any("connect failed" in m for m in uf.logged)


def test_control_exception_is_caught(uf):
    run = FakeRunner(uf)

    def raising(argv, **kw):
        if argv[0] == uf.UNBOUND_CONTROL:
            raise subprocess.TimeoutExpired(argv, 10)
        return run(argv, **kw)
    result, _ = flow(uf, raising)
    assert result["status"] == "failed"


def test_main_never_fails(uf, monkeypatch):
    def boom():
        raise RuntimeError("x")
    monkeypatch.setattr(uf, "run_flush", boom)
    assert uf.main() == 0


def test_unbound_port(uf, tmp_path):
    st = tmp_path / "st.json"
    conf = tmp_path / "unbound.conf"
    conf.write_text("server:\nport: 5353\n")
    assert uf.unbound_port(str(st), str(conf)) == 5353
    st.write_text('{"unbound_port": 53530}')
    assert uf.unbound_port(str(st), str(conf)) == 53530
    assert uf.unbound_port(str(tmp_path / "x"), str(tmp_path / "y")) == 53
